const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const percentage=value=>formatAnalysisNumber(value*100)+'%';
let current=null;
export function disposeDataAnalysis(){current?.dispose();current=null;}
