export function mountDataAnalysis({container=document.querySelector('.dashboard'),ctx={},draftId,projectId,loadWorkbook=()=>import('./assets/analysis-workbook.js'),loadStatistics=()=>import('./assets/analysis-statistics.js')}={}){
 disposeDataAnalysis();if(!container)return null;
 const drafts=list(keys.drafts),fresh=new URLSearchParams(String(globalThis.location?.hash||'').split('?')[1]||'').has('new'),loaded=draftId?drafts.find(row=>String(row.id)===String(draftId)&&row.tool==='analysis'):fresh?undefined:drafts.filter(row=>row.tool==='analysis'&&row.analysisResume&&!row.archived&&(!projectId||String(row.projectId)===String(projectId))).sort((a,b)=>String(b.updatedAt||'').localeCompare(String(a.updatedAt||'')))[0],saved=loaded?.analysisState||{};
 let active=true,busy=false,computing=false,computeRevision=0,workbookFile=null,importRevision=0,savedId=loaded?.id||null,step=1,dataset=null,columns=[],result=null,saveFailure=false,restorationError='',correlationRestorationFailed=false;
 const initial=saved.form||{};
 try{if(saved.dataset){dataset=validateAnalysisDataset(saved.dataset);columns=defaultAnalysisColumns(dataset);if(saved.columns!==undefined){if(!Array.isArray(saved.columns)||saved.columns.length!==dataset.headers.length||saved.columns.some((column,index)=>!column||column.index!==index||!['numeric','category'].includes(column.type)||typeof column.include!=='boolean'))restorationError='此前的列设置无效，已按数据重新识别；请核对后重新计算。';else columns=saved.columns.map(column=>({...column}));}}}catch(e){restorationError=e.message;}
 container.classList.add('creation-page','data-analysis-page');container.classList.remove('category-view');
 container.innerHTML=`${writingDetailHeading('analysis')}<section class="analysis-workflow" aria-label="数据分析步骤"><div class="analysis-workflow-head"><div><span>DATA ANALYSIS</span><h2>从真实数据，得到可核对的结果</h2><p>只需三步，在本地完成描述统计与基础推断分析。</p></div><span class="analysis-local-badge">浏览器本地计算 · 不消耗 AI 积分</span></div><ol>${['基础信息填写','数据文件上传','输出结果'].map((name,i)=>`<li><button type="button" id="analysis-step-${i+1}" data-analysis-step="${i+1}"><span class="analysis-step-number">${i+1}</span><span><b>${name}</b><small>${['明确分析主题与数据来源','上传 CSV / XLSX，核对数据列','查看统计口径与导出报告'][i]}</small></span></button></li>`).join('')}</ol></section><main class="analysis-body"><div class="analysis-processing" id="analysis-processing" role="status" aria-live="polite" hidden><span class="generation-wait-spinner" aria-hidden="true"></span><div><b>正在处理数据</b><p id="analysis-processing-message"></p></div></div><section class="card analysis-panel" id="analysis-basic-panel"><div class="analysis-panel-title"><div><span class="analysis-kicker">STEP 01 · RESEARCH BRIEF</span><h2>基础信息填写</h2><p>先明确分析主题。研究问题与数据来源可稍后补充。</p></div><span class="badge neutral">可自动保存</span></div><form id="writing-form"><div class="analysis-form-grid"><div class="analysis-form-wide"><label for="writing-title">分析标题 <span aria-hidden="true">*</span></label><input id="writing-title" required minlength="2" maxlength="200" placeholder="例如：数字阅读服务满意度数据分析" value="${esc(initial.title??loaded?.title??'')}"></div><div class="analysis-form-wide"><label for="analysis-question">研究问题（可选）</label><textarea id="analysis-question" rows="3" maxlength="2000" placeholder="例如：不同阅读习惯的样本中，满意度分布有什么特点？">${esc(initial.question||'')}</textarea></div><div class="analysis-form-wide"><label for="analysis-variables">变量信息（可选）</label><textarea id="analysis-variables" rows="3" maxlength="4000" placeholder="说明变量含义、单位、分组和编码，例如：组别A/B、满意度1至5分">${esc(initial.variables||'')}</textarea></div><div class="analysis-form-wide"><label for="analysis-previous">已有探索性分析（可选）</label><textarea id="analysis-previous" rows="3" maxlength="4000" placeholder="填写已经实际完成的检查或发现；未做过可以留空">${esc(initial.previousAnalysis||'')}</textarea></div><div class="analysis-form-wide"><label for="analysis-methods">预期方法（可选）</label><textarea id="analysis-methods" rows="3" maxlength="4000" placeholder="说明研究希望使用的方法；实际仅运行下一步明确勾选的受支持方法">${esc(initial.expectedMethods||'')}</textarea></div><div><label for="analysis-source">真实数据来源（可选）</label><textarea id="analysis-source" rows="3" maxlength="2000" placeholder="例如：本人问卷回收；请勿填写尚未采集的数据">${esc(initial.source||'')}</textarea></div><div><label for="analysis-project">所属项目（可选）</label><select id="analysis-project" data-project-picker data-project-ref="${esc(initial.projectId||loaded?.projectId||projectId||'')}">${projectPickerOptions(initial.projectId||loaded?.projectId||projectId||'')}</select><p class="field-note">分析记录可以从“文件管理”继续打开。</p></div></div><div class="analysis-panel-actions"><button class="btn secondary" type="button" id="writing-save">保存草稿</button><button class="btn primary" type="submit" id="analysis-next">下一步：数据文件上传 →</button></div></form></section><section class="card analysis-panel" id="analysis-upload-panel" hidden><div class="analysis-panel-title"><div><span class="analysis-kicker">STEP 02 · YOUR DATA</span><h2>上传并核对数据</h2><p>首行须为列名，每行代表一条记录。数据会真实解析，结果来自你确认的数据列。</p></div><span class="badge neutral">CSV / TSV / XLSX</span></div><label class="analysis-upload" for="analysis-file"><span class="analysis-upload-icon" aria-hidden="true">↥</span><b>选择数据文件</b><span>CSV / TSV / XLSX，最大 10 MB · 10,000 行 · 60 列</span><small>文本文件需 UTF-8；XLSX 需选择工作表。旧版 XLS 和含宏的 XLSM 请先另存为 XLSX。</small><input id="analysis-file" type="file" accept=".csv,.tsv,.xlsx,text/csv,text/tab-separated-values,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"></label><p class="analysis-upload-hint">本地解析不向 AI 上传数据。缺失值口径：${missingValueDescription}。如需账户同步，请在账户草稿中明确保存；单份账户草稿上限 750 KB，较大的数据请使用本地分析与导出。</p><section id="analysis-workbook-panel" hidden><label for="analysis-workbook-sheet">选择要分析的工作表</label><select id="analysis-workbook-sheet"></select><button type="button" class="btn secondary" id="analysis-workbook-use">采用此工作表</button><p class="field-note">首行作为列名；数值读取底层值，不保留显示格式或前导零；日期转为 UTC ISO 文本，布尔值为 TRUE/FALSE 分类文本；公式只读取缓存结果，无缓存或有错误会停止导入。隐藏行列照常导入，合并单元格需先取消合并。工作簿原件仅留在本页内存，不上传。</p></section><div id="analysis-dataset" hidden><div class="analysis-file-summary" id="analysis-file-summary"></div><details class="analysis-preview"><summary>查看数据预览（前 10 行）</summary><div class="analysis-table-scroll" id="analysis-preview-table"></div></details><div class="analysis-columns-head"><div><h3>选择分析列与类型</h3><p>常见编号、姓名与联系方式默认排除；可手动调整。混合文本列默认视为分类变量。</p></div><button type="button" id="analysis-clear-file" class="btn secondary">移除数据</button></div><div class="analysis-table-scroll" id="analysis-column-table"></div><div class="analysis-correlation"><div><h3>Pearson 相关（可选）</h3><p>仅对两列数值的有效配对计算，至少 3 对；同时报告双侧 p 值及检验假设，不代表因果。</p></div><label for="analysis-correlation-enabled"><input id="analysis-correlation-enabled" type="checkbox"> 计算两列的线性相关</label><div id="analysis-correlation-fields" hidden><label for="analysis-correlation-x">数值变量 X</label><select id="analysis-correlation-x"></select><label for="analysis-correlation-y">数值变量 Y</label><select id="analysis-correlation-y"></select></div></div><div class="analysis-correlation"><div><h3>Welch 独立样本 t 检验（可选）</h3><p>比较两个独立组的数值均值；每组至少2个有效观测，分组列须恰好两个非缺失组。双侧检验、95%置信区间。</p></div><label><input id="analysis-welch-enabled" type="checkbox"> 比较两个独立组的均值</label><div id="analysis-welch-fields" hidden><label for="analysis-welch-group">分组变量</label><select id="analysis-welch-group"></select><label for="analysis-welch-value">数值变量</label><select id="analysis-welch-value"></select></div></div><div class="analysis-correlation"><div><h3>OLS 一元线性回归（可选）</h3><p>含截距，至少3个有效成对观测；报告系数、R²、斜率双侧p值和95%区间。请核对线性、独立和误差假设。</p></div><label><input id="analysis-regression-enabled" type="checkbox"> 拟合 Y 与 X 的线性关系</label><div id="analysis-regression-fields" hidden><label for="analysis-regression-x">自变量 X</label><select id="analysis-regression-x"></select><label for="analysis-regression-y">因变量 Y</label><select id="analysis-regression-y"></select></div></div></div><div class="analysis-panel-actions"><button type="button" class="btn secondary" data-analysis-back="1">← 上一步</button><button type="button" class="btn primary" id="analysis-compute">计算并输出结果 →</button></div></section><section class="card analysis-panel" id="analysis-results-panel" hidden><div class="analysis-panel-title"><div><span class="analysis-kicker">STEP 03 · VERIFIED CALCULATIONS</span><h2>分析结果</h2><p>真实计算，口径透明；切换数据或分析列后，需要重新计算。</p></div><span class="analysis-local-badge">本地真实计算</span></div><div id="analysis-results"></div><div class="analysis-panel-actions analysis-export-actions"><button type="button" class="btn secondary" data-analysis-back="2">← 调整数据与分析列</button><button type="button" class="btn secondary" id="analysis-copy">复制报告</button><button type="button" class="btn secondary" id="analysis-export-csv">导出统计 CSV</button><button type="button" class="btn secondary" id="analysis-export-txt">导出 TXT</button>${documentExportButtons('analysis-report',{docxOnly:true})}<button type="button" class="btn primary" id="analysis-save-result">保存到文件管理</button></div></section><p id="writing-status" class="analysis-status" role="status" aria-live="polite"></p><p id="analysis-error" class="analysis-error" role="alert"></p><aside class="analysis-boundary"><b>结果由数据决定</b><p>本功能提供描述统计、分类频数、Pearson 相关与双侧p值、Welch独立样本t检验及OLS一元回归。检验依赖所列假设；p值不是效果大小或因果证明。暂不提供ANOVA、卡方、聚类、PCA、因子与信效度分析，也不自动替用户作研究结论；没有真实数据时不会生成数值报告。原始解析值随本地草稿保存，请及时导出并妥善保护个人信息。</p></aside></main>`;
 decorateWritingDetail(container,'analysis');
 const $=selector=>container.querySelector(selector),alive=()=>active&&container.isConnected&&current?.root===container&&!!$('#writing-form');
 const formValues=()=>({title:$('#writing-title').value.trim(),question:$('#analysis-question').value.trim(),source:$('#analysis-source').value.trim(),variables:$('#analysis-variables').value.trim(),previousAnalysis:$('#analysis-previous').value.trim(),expectedMethods:$('#analysis-methods').value.trim(),projectId:$('#analysis-project').value});
 const correlationValues=()=>$('#analysis-correlation-enabled').checked?{x:$('#analysis-correlation-x').value,y:$('#analysis-correlation-y').value}:null;
 const inferenceValues=()=>Object.fromEntries([['welch',['group','value']],['regression',['x','y']]].map(([method,axes])=>[method,$('#analysis-'+method+'-enabled').checked?Object.fromEntries(axes.map(axis=>[axis,$('#analysis-'+method+'-'+axis).value])):null]));
 const snapshot=()=>({form:formValues(),step,dataset,columns,correlation:correlationValues(),...inferenceValues(),hasResult:!!result});
 const status=message=>{if(alive()){$('#writing-status').textContent=message;const waiting=$('#analysis-processing');if(waiting){waiting.hidden=!busy&&!computing;if(!waiting.hidden)$('#analysis-processing-message').textContent=message;}}};
 const showError=message=>{if(alive())$('#analysis-error').textContent=message||'';};
 const report=()=>analysisReportText(result,{...formValues(),fileName:dataset?.fileName||'',sheetName:dataset?.sheetName||'',importNotes:dataset?.importNotes||''});
 function invalidate(){computeRevision++;computing=false;$('#analysis-processing').hidden=!busy;$('#analysis-compute').disabled=busy;result=null;$('#analysis-results').innerHTML='';if(step===3)showStep(2);updateSteps();}
 function updateSteps(){for(const b of container.querySelectorAll('[data-analysis-step]')){const value=Number(b.dataset.analysisStep),done=value===1?step>1:value===2?!!result:false;b.classList.toggle('is-current',value===step);b.classList.toggle('is-done',done);b.setAttribute('aria-current',value===step?'step':'false');b.querySelector('.analysis-step-number').textContent=done?'✓':String(value);}container.dataset.analysisStep=String(step);}
 function showStep(next){return withStableView(container,()=>{step=next;for(const [number,id]of [[1,'analysis-basic-panel'],[2,'analysis-upload-panel'],[3,'analysis-results-panel']])$('#'+id).hidden=number!==step;updateSteps();});}
 function validateBasic(){if(formValues().title.length<2){showError('请填写至少 2 个字的分析标题。');showStep(1);$('#writing-title').focus({preventScroll:true});return false;}return true;}
 function saveDraft({announce=false}={}){if(!alive()||busy||computing)return false;try{const rows=list(keys.drafts),previous=rows.find(row=>String(row.id)===String(savedId))||loaded,now=new Date(Math.max(Date.now(),Date.parse(previous?.updatedAt||'')+1||0)).toISOString(),form=formValues(),text=result?report():[form.title||'未命名数据分析','分析准备草稿',form.question?'研究问题：'+form.question:'',form.source?'用户填写的数据来源：'+form.source:'',form.variables?'变量信息：'+form.variables:'',form.previousAnalysis?'已有探索性分析：'+form.previousAnalysis:'',form.expectedMethods?'预期方法：'+form.expectedMethods:'',dataset?`已保留解析数据：${dataset.rows.length} 行、${dataset.headers.length} 列；尚未确认结果时不生成数值报告。`:'尚未上传数据，不存在统计结果。'].filter(Boolean).join('\n'),item={...previous,id:savedId||crypto.randomUUID(),title:form.title||'未命名数据分析',tool:'analysis',projectId:form.projectId,text,html:text.split('\n').map(line=>'<p>'+esc(line)+'</p>').join(''),analysisState:{version:1,...snapshot()},analysisResume:true,createdAt:previous?.createdAt||now,updatedAt:now,stage:result?'completed':'draft'};const index=rows.findIndex(row=>String(row.id)===String(item.id));if(index>=0)rows[index]=item;else rows.unshift(item);write(keys.drafts,rows);savedId=item.id;saveFailure=false;markEditorSaved();if(announce)status(hasDraftScope()?'当前编辑已暂存，请点击“保存到账户”完成同步。':'分析草稿已保存，可在“文件管理”继续；解析数据已一并保留。');return item;}catch{saveFailure=true;status('草稿保存失败，可能是浏览器存储空间不足。当前数据仍保留，请导出报告后重试；请勿直接关闭页面。');return false;}}
 function fillCorrelation(preferred){const options=columns.filter(column=>column.include&&column.type==='numeric'),before=preferred||correlationValues(),markup='<option value="">请选择</option>'+options.map(column=>`<option value="${column.index}">${esc(dataset.headers[column.index])}</option>`).join('');$('#analysis-correlation-x').innerHTML=markup;$('#analysis-correlation-y').innerHTML=markup;if(before){$('#analysis-correlation-x').value=String(before.x);$('#analysis-correlation-y').value=String(before.y);}$('#analysis-correlation-fields').hidden=!$('#analysis-correlation-enabled').checked;}
 function fillInference(preferred={}){fillCorrelation(preferred.correlation);for(const [method,axes]of [['welch',['group','value']],['regression',['x','y']]]){const before=preferred[method]||inferenceValues()[method];for(const axis of axes){const select=$('#analysis-'+method+'-'+axis),options=columns.filter(column=>column.include&&(axis==='group'||column.type==='numeric'));select.innerHTML='<option value="">请选择</option>'+options.map(column=>`<option value="${column.index}">${esc(dataset.headers[column.index])}</option>`).join('');if(before)select.value=String(before[axis]);}$('#analysis-'+method+'-fields').hidden=!$('#analysis-'+method+'-enabled').checked;}}
 function resetMethods(){for(const method of ['correlation','welch','regression']){$('#analysis-'+method+'-enabled').checked=false;$('#analysis-'+method+'-fields').hidden=true;}}
 function renderDataset(){const area=$('#analysis-dataset');area.hidden=!dataset;if(!dataset){$('#analysis-file-summary').textContent='';return;}const inspected=inspectAnalysisColumns(dataset);$('#analysis-file-summary').innerHTML=`<span aria-hidden="true">▦</span><div><b>${esc(dataset.fileName||'已保存的数据')}${dataset.sheetName?' · 工作表：'+esc(dataset.sheetName):''}</b><small>${dataset.rows.length.toLocaleString('zh-CN')} 行记录 · ${dataset.headers.length} 列 · 解析值将随草稿保留</small></div>`;$('#analysis-preview-table').innerHTML=`<table><thead><tr>${dataset.headers.map(name=>`<th scope="col">${esc(name)}</th>`).join('')}</tr></thead><tbody>${dataset.rows.slice(0,10).map(row=>`<tr>${row.map(value=>`<td>${esc(value||'（空）')}</td>`).join('')}</tr>`).join('')}</tbody></table>`;$('#analysis-column-table').innerHTML=`<table class="analysis-column-table"><thead><tr><th scope="col">参与分析</th><th scope="col">数据列</th><th scope="col">变量类型</th><th scope="col">缺失</th><th scope="col">数值 / 非数字</th></tr></thead><tbody>${inspected.map(column=>{const selected=columns.find(item=>item.index===column.index)||{include:false,type:column.type};return `<tr><td><input type="checkbox" data-analysis-include="${column.index}" aria-label="分析列 ${esc(column.name)}" ${selected.include?'checked':''}></td><th scope="row">${esc(column.name)}${column.identifier?'<small>默认排除标识符</small>':''}</th><td><select data-analysis-type="${column.index}" aria-label="${esc(column.name)}的变量类型"><option value="numeric" ${selected.type==='numeric'?'selected':''}>数值变量</option><option value="category" ${selected.type==='category'?'selected':''}>分类变量</option></select></td><td>${column.missing} / ${dataset.rows.length}</td><td>${column.numeric} / ${column.nonNumeric}</td></tr>`;}).join('')}</tbody></table>`;fillInference();}
 function renderResults(){if(!result)return;const numeric=result.columns.filter(c=>c.type==='numeric'),category=result.columns.filter(c=>c.type==='category');$('#analysis-results').innerHTML=`<div class="analysis-stat-grid"><article><span>原始记录数</span><b>${result.rows}</b><small>每行代表一条记录</small></article><article><span>参与分析的列</span><b>${result.selectedColumns}</b><small>已排除 ${result.excludedColumns} 列</small></article><article><span>缺失单元格率</span><b>${percentage(result.missingRate)}</b><small>所选 ${result.rows*result.selectedColumns} 个单元格中缺失 ${result.missing} 个</small></article></div><div class="analysis-result-note"><b>数据口径</b><p>缺失值：${missingValueDescription}。数值列中的非数字值另行排除，不计入缺失数。每列有效数可能不同；标准差采用样本标准差（n−1）。</p></div>${numeric.length?`<section class="analysis-result-section"><h3>数值变量描述统计</h3><div class="analysis-table-scroll"><table><thead><tr>${['变量','有效 n','缺失','非数字排除','均值','中位数','最小值','最大值','样本标准差'].map(name=>`<th scope="col">${name}</th>`).join('')}</tr></thead><tbody>${numeric.map(c=>`<tr><th scope="row">${esc(c.name)}</th><td>${c.n}</td><td>${c.missing}</td><td>${c.invalid}</td>${['mean','median','min','max','sampleSD'].map(key=>`<td>${formatAnalysisNumber(c[key])}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="field-note">n ＜ 2 时不计算样本标准差；极端数值超出可表示范围时显示“未计算”。</p></section>`:''}${category.map(c=>`<section class="analysis-result-section"><div class="analysis-frequency-title"><h3>${esc(c.name)} · 分类频数</h3><span>有效 ${c.n} · 缺失 ${c.missing} · ${c.distinct} 类</span></div><div class="analysis-table-scroll"><table><thead><tr><th scope="col">类别</th><th scope="col">频数</th><th scope="col">有效值占比</th></tr></thead><tbody>${c.frequencies.slice(0,20).map(row=>`<tr><th scope="row">${esc(row.value)}</th><td>${row.count}</td><td><span class="analysis-frequency-bar"><i style="width:${Math.round(row.rate*100)}%"></i><b>${percentage(row.rate)}</b></span></td></tr>`).join('')}</tbody></table></div>${c.frequencies.length>20?'<p class="field-note">页面显示频数最高的前 20 类；导出的 CSV 和报告包含全部类别。</p>':''}</section>`).join('')}${result.correlation?`<section class="analysis-correlation-result"><span>Pearson 相关</span><h3>${esc(result.correlation.xName)} × ${esc(result.correlation.yName)}</h3><b>${result.correlation.r===null?'未计算':'r = '+formatAnalysisNumber(result.correlation.r)}</b><p>有效成对样本 n = ${result.correlation.n}。${esc(result.correlation.note)}</p></section>`:''}<p class="analysis-result-final">统计仅基于本次导入的数据，不验证采集真实性；推断仅在所列假设成立时适用。请结合研究设计核对口径，勿将相关关系解释为因果关系。</p>`;}
 function inferenceResults(){const parts=[];if(result?.correlation&&Object.hasOwn(result.correlation,'pValue'))parts.push(`<section class="analysis-correlation-result"><h3>Pearson 双侧检验</h3><p>p：${formatAnalysisP(result.correlation.pValue)}；自由度 ${result.correlation.df??'未计算'}</p><p>${esc(result.correlation.inferenceNote)}</p></section>`);if(result?.welch){const w=result.welch;parts.push(`<section class="analysis-correlation-result"><h3>Welch 独立样本 t 检验</h3><p>${esc(w.valueName)} 按 ${esc(w.groupName)} 分组</p>${w.groups.map(g=>`<p>${esc(g.label)}：n=${g.n}；均值 ${formatAnalysisNumber(g.mean)}；样本标准差 ${formatAnalysisNumber(g.sampleSD)}</p>`).join('')}<p>t=${formatAnalysisNumber(w.t)}；自由度 ${formatAnalysisNumber(w.df)}；双侧 p：${formatAnalysisP(w.pValue)}</p><p>第一组减第二组的均值差 ${formatAnalysisNumber(w.difference)}；95%区间 [${w.ci95.map(formatAnalysisNumber).join(', ')}]；排除 ${w.excludedRows} 行</p><p>${esc(w.note)}</p></section>`);}if(result?.regression){const r=result.regression;parts.push(`<section class="analysis-correlation-result"><h3>OLS 一元线性回归</h3><p>${esc(r.yName)} ~ ${esc(r.xName)}；有效成对 n=${r.n}；排除 ${r.excludedRows} 行</p><p>截距 ${formatAnalysisNumber(r.intercept)}；斜率 ${formatAnalysisNumber(r.slope)}；R²=${formatAnalysisNumber(r.rSquared)}</p><p>斜率标准误 ${formatAnalysisNumber(r.slopeSE)}；双侧 p：${formatAnalysisP(r.pValue)}；自由度 ${r.df}</p><p>斜率95%区间：${r.slopeCI95?'['+r.slopeCI95.map(formatAnalysisNumber).join(', ')+']':'未计算'}</p><p>${esc(r.note)}</p></section>`);}return parts.join('');}
 async function compute({restoring=false}={}){if(busy||computing)return false;if(!validateBasic())return false;if(!dataset){showStep(2);showError('请先上传并确认包含真实数据的 CSV、TSV 或 XLSX 工作表。');return false;}const revision=++computeRevision,data=dataset,selected=columns.map(column=>({...column})),correlation=correlationValues(),methods=inferenceValues();try{validateAnalysisCorrelation(correlation,selected);validateAnalysisInference(methods,selected);computing=true;$('#analysis-compute').disabled=true;status('正在检查数据列、有效样本与缺失值…');await new Promise(resolve=>{const frame=container.ownerDocument.defaultView.requestAnimationFrame;if(frame)frame(()=>frame(resolve));else queueMicrotask(resolve);});if(!alive()||revision!==computeRevision)return false;let next=analyzeDataset(data,{columns:selected,correlation});if(correlation||methods.welch||methods.regression){computing=true;$('#analysis-compute').disabled=true;status('正在本地计算并校验检验条件…');const engine=await loadStatistics();if(!alive()||revision!==computeRevision)return false;next=engine.applyAnalysisInference(data,{columns:selected,correlation,...methods});}if(!alive()||revision!==computeRevision)return false;computing=false;result=next;showError('');renderResults();$('#analysis-results').insertAdjacentHTML('beforeend',inferenceResults());showStep(3);if(!saveDraft())return false;status(restoring?'已恢复并复算草稿数据，无需重新选择原文件；请核对有效样本、缺失口径与检验假设。':'统计计算已完成，结果与解析数据已暂存；请核对有效样本、缺失口径与检验假设。');return true;}catch(e){if(alive()&&revision===computeRevision){invalidate();showError(e.message||'计算未完成，请检查数据和列类型。');}return false;}finally{if(alive()&&revision===computeRevision){computing=false;$('#analysis-compute').disabled=busy;$('#analysis-processing').hidden=!busy;}}}
 async function download(text,extension,type){if(!result){showError('请先完成计算，不能导出过期或空白结果。');return;}try{const exported=await exportFile((formValues().title||'数据分析报告')+'.'+extension,text,type,{sourceType:'writing'});status(exported.message);}catch(error){showError(error.message);}}
 $('#writing-form').addEventListener('submit',event=>{event.preventDefault();if(!validateBasic())return;showError('');showStep(2);saveDraft();});
 $('#writing-save').addEventListener('click',()=>saveDraft({announce:true}));
 for(const b of container.querySelectorAll('[data-analysis-step]'))b.addEventListener('click',()=>{if(busy||computing)return;const next=Number(b.dataset.analysisStep);if(next===1){showStep(1);saveDraft();return;}if(!validateBasic())return;if(next===3){compute();return;}showError('');showStep(2);saveDraft();});
 for(const b of container.querySelectorAll('[data-analysis-back]'))b.addEventListener('click',()=>{showStep(Number(b.dataset.analysisBack));saveDraft();});
 $('#writing-form').addEventListener('input',()=>{if(result||computing)invalidate();});$('#analysis-project').addEventListener('change',()=>{if(result||computing)invalidate();});
 $('#analysis-file').addEventListener('change',async()=>{const file=$('#analysis-file').files?.[0];if(!file)return;const revision=++importRevision;busy=false;workbookFile=null;$('#analysis-workbook-panel').hidden=true;dataset=null;columns=[];invalidate();renderDataset();resetMethods();showError('');if(!/\.(csv|tsv|xlsx)$/i.test(file.name)){showError('仅支持 UTF-8 CSV 或 TSV，以及不含宏的 XLSX。旧版 XLS / XLSM 请先另存为 XLSX。');$('#analysis-file').value='';saveDraft();return;}if(file.size>analysisLimits.bytes){showError('数据文件不能超过 10 MB，请拆分后上传。');$('#analysis-file').value='';saveDraft();return;}busy=true;$('#analysis-compute').disabled=true;status('正在本地读取并校验数据…');try{const buffer=typeof file.arrayBuffer==='function'?await file.arrayBuffer():null;if(!alive()||revision!==importRevision)return;if(/\.xlsx$/i.test(file.name)){if(!buffer)throw Error('浏览器无法读取工作簿，请重新选择文件。');const reader=await loadWorkbook();if(!alive()||revision!==importRevision)return;const workbook=await reader.readAnalysisWorkbook(buffer,{fileName:file.name});if(!alive()||revision!==importRevision)return;workbookFile={workbook,name:file.name};$('#analysis-workbook-sheet').innerHTML='<option value="">请选择工作表</option>'+workbook.sheets.map(sheet=>`<option value="${esc(sheet.id)}">${esc(sheet.name)}${sheet.hidden?'（隐藏表）':''} · ${sheet.rows} 行 · ${sheet.columns} 列</option>`).join('');if(workbook.sheets.length===1)$('#analysis-workbook-sheet').value=workbook.sheets[0].id;$('#analysis-workbook-panel').hidden=false;status('工作簿已在本地读取，请选择并采用一个工作表；未采用前不会生成结果。');}else{let text;if(buffer){try{text=new TextDecoder('utf-8',{fatal:true}).decode(buffer);}catch{throw Error('文件不是有效 UTF-8 编码，请另存为 UTF-8 CSV 或 TSV。');}}else text=await file.text();if(!alive()||revision!==importRevision)return;dataset=parseAnalysisDelimited(text,{fileName:file.name});columns=defaultAnalysisColumns(dataset);renderDataset();status(`已真实解析 ${dataset.rows.length} 行、${dataset.headers.length} 列。请核对分析列后计算。`);}}catch(e){if(alive()&&revision===importRevision){dataset=null;columns=[];workbookFile=null;$('#analysis-workbook-panel').hidden=true;renderDataset();showError(e.message||'文件解析失败，请检查格式。');status('新文件未通过校验，未保留旧结果；请重新选择数据文件。');}}finally{if(alive()&&revision===importRevision){busy=false;$('#analysis-processing').hidden=true;$('#analysis-compute').disabled=false;$('#analysis-file').value='';saveDraft();}}});
 $('#analysis-workbook-sheet').addEventListener('change',()=>{dataset=null;columns=[];invalidate();renderDataset();resetMethods();saveDraft();status('工作表已切换，请采用当前工作表后重新计算。');});
 $('#analysis-workbook-use').addEventListener('click',()=>{if(!workbookFile)return;try{dataset=workbookFile.workbook.select($('#analysis-workbook-sheet').value);columns=defaultAnalysisColumns(dataset);invalidate();renderDataset();showError('');saveDraft();status(`已采用工作表“${dataset.sheetName}”：${dataset.rows.length} 行、${dataset.headers.length} 列；请核对预览与类型。`);}catch(e){dataset=null;columns=[];invalidate();renderDataset();showError(e.message);saveDraft();}});
 $('#analysis-clear-file').addEventListener('click',()=>{importRevision++;dataset=null;columns=[];workbookFile=null;$('#analysis-workbook-panel').hidden=true;invalidate();renderDataset();resetMethods();saveDraft();status('数据与此前统计结果已移除；不会继续导出旧结果。');});
 $('#analysis-column-table').addEventListener('change',event=>{const include=event.target.dataset.analysisInclude,type=event.target.dataset.analysisType;if(include===undefined&&type===undefined)return;const index=Number(include??type),column=columns.find(item=>item.index===index);if(!column)return;if(include!==undefined)column.include=event.target.checked;else column.type=event.target.value;invalidate();fillInference();saveDraft();status('分析列已调整，请重新计算；旧结果已失效。');});
 for(const [method,axes]of [['correlation',['x','y']],['welch',['group','value']],['regression',['x','y']]]){$('#analysis-'+method+'-enabled').addEventListener('change',()=>{invalidate();$('#analysis-'+method+'-fields').hidden=!$('#analysis-'+method+'-enabled').checked;fillInference();saveDraft();});for(const axis of axes)$('#analysis-'+method+'-'+axis).addEventListener('change',()=>{invalidate();saveDraft();});}
 $('#analysis-compute').addEventListener('click',compute);
 $('#analysis-export-txt').addEventListener('click',()=>download(report(),'txt','text/plain;charset=utf-8'));$('#analysis-export-csv').addEventListener('click',()=>download(analysisResultsCSV(result,{...formValues(),fileName:dataset?.fileName,sheetName:dataset?.sheetName,importNotes:dataset?.importNotes}),'csv','text/csv;charset=utf-8'));
 $('#analysis-copy').addEventListener('click',async()=>{if(!result)return;try{await navigator.clipboard.writeText(report());if(alive())status('分析报告已复制。');}catch{if(alive())showError('浏览器未允许复制，请使用 TXT 导出。');}});
 $('#analysis-save-result').addEventListener('click',()=>{if(!result){showError('请先计算结果。');return;}const item=saveDraft({announce:true});if(item&&!hasDraftScope()){try{recordTask({id:'draft-'+item.id,title:item.title,kind:'数据分析 · 本地真实计算',status:'completed',url:'#draft/'+item.id});status('已保存到“文件管理”；解析数据与分析口径一并保留。');}catch{status('成果已保存，但任务记录未保存；可从“文件管理”继续打开。');}}});
 bindDocumentExports('analysis-report',report,()=>formValues().title,$('#writing-status'),{docxOnly:true,isCurrent:alive,getDocumentOptions:()=>({documentKind:'writing',metadata:{title:formValues().title}})});
 const instance={root:container,dispose(){if(!active)return;active=false;importRevision++;computeRevision++;workbookFile=null;busy=false;computing=false;},hasWork:()=>alive()&&(busy||computing||saveFailure),routeGuard:()=>!busy&&!computing&&saveDraft()!==false};current=instance;
 registerEditor({label:'数据分析',ctx,getValue:snapshot,save:saveDraft,saveDraft,busy:()=>busy||computing,dispose:instance.dispose});
 if(dataset){renderDataset();for(const method of ['correlation','welch','regression'])if(saved[method]!==null&&saved[method]!==undefined)$('#analysis-'+method+'-enabled').checked=true;fillInference({correlation:saved.correlation,welch:saved.welch,regression:saved.regression});try{validateAnalysisCorrelation(saved.correlation,columns);validateAnalysisInference({welch:saved.welch,regression:saved.regression},columns);}catch(e){correlationRestorationFailed=true;restorationError=(restorationError?restorationError+' ':'')+'此前 Pearson 或推断设置无法恢复：'+e.message;}step=Math.min(2,Math.max(1,Number(saved.step)||1));}
 showStep(step);if(restorationError)showError(restorationError);else if(dataset)status('已恢复草稿中的真实解析数据，无需重新选择原文件；结果依据当前口径重新计算。');
 if(correlationRestorationFailed&&saved.hasResult)saveDraft();
 if(dataset&&saved.hasResult&&!restorationError)void compute({restoring:true});
 // Restoration is itself synchronous and must not mark an unchanged page dirty.
 markEditorSaved();return instance;
}
